/* Lime side of the C11 differential.  c11.l's flex scanner (shared with the
** bison side) produces yacc token codes; map them to the Lime codes that
** y2lime_min.py assigned (c11_map.h, generated by run_c11.sh). */
#include <stdio.h>
#include <stdlib.h>
#include "y.tab.h"       /* bison's codes: what the scanner returns */
#include "c11_map.h"     /* int lime_map(int yacc_code) */
void *YAlloc(void *(*)(size_t)); void YFree(void *, void (*)(void *));
void Y(void *, int, int);
int yylex(void);
static int nerr;
void yyerror(const char *s) { (void)s; nerr++; }   /* c11.l: unterminated comment */
int *yy_err_counter(void) { return &nerr; }
int main(void) {
    void *p = YAlloc(malloc);
    int t, ntok = 0;
    while ((t = yylex()) > 0) {
        int k = lime_map(t);
        ntok++;
        if (k < 0) { nerr++; break; }
        Y(p, k, 0);
        if (nerr) break;   /* c11.y has no error rule: stop like yyparse() */
    }
    if (!nerr) Y(p, 0, 0);
    YFree(p, free);
    /* the token index of the error must match bison's, not just the verdict */
    if (nerr) { printf("REJECT@%d\n", t > 0 ? ntok : ntok + 1); return 1; }
    puts("ACCEPT"); return 0;
}
